{
  "R02": {
    "label": "relevant",
    "reason": "Der Lageberich enthält einen Prognoseabschnitt ('Ausblick auf das Geschäftsjahr 2025'), der den Prognosezeitraum implizit oder explizit nennt. Die Pflicht ist immer anwendbar, wenn ein Prognosebericht vorhanden ist."
  },
  "R03": {
    "label": "relevant",
    "reason": "Ein Prognosebericht ist vorhanden, daher ist die Pflicht zur Angabe wesentlicher Annahmen anwendbar, auch wenn diese im vorliegenden Fall nicht detailliert dargestellt sind."
  },
  "R04": {
    "label": "relevant",
    "reason": "Im Lageberich werden bedeutsame finanzielle und nichtfinanzielle Leistungsindikatoren genannt. Die Pflicht, Prognosen zu diesen abzugeben, ist immer anwendbar, da ein Prognosebericht existiert."
  },
  "R10": {
    "label": "relevant",
    "reason": "Ein Risiko- und Chancenbericht ist vorhanden. Die Pflicht zur Darstellung der Bedeutung (z.B. Rangordnung) ist immer anwendbar."
  },
  "R11": {
    "label": "relevant",
    "reason": "Ein Risiko- und Chancenbericht ist vorhanden. Die Pflicht zur Zusammenfassung der Gesamtrisiko- und Chancenlage ist immer anwendbar, und der Lageberich enthält zusammenfassende Aussagen."
  },
  "R12": {
    "label": "relevant",
    "reason": "Das Unternehmen verwendet Finanzinstrumente (z.B. Forderungen, Verbindlichkeiten). Da dies für die Beurteilung der Lage und Entwicklung relevant sein kann, ist die Bedingung erfüllt, und die Pflicht ist somit anwendbar."
  },
  "R14": {
    "label": "relevant",
    "reason": "Die Pflicht zur Analyse der Ertragslage ist für alle Jahresabschlüsse mit Lagebericht anwendbar. Der Lageberich enthält eine Analyse der Ertragslage."
  },
  "R15": {
    "label": "relevant",
    "reason": "Die Pflicht zur Analyse der Finanzlage ist für alle Jahresabschlüsse mit Lagebericht anwendbar. Der Lageberich enthält eine Analyse der Finanzlage, einschließlich Kapitalstruktur und Liquidität."
  },
  "R17": {
    "label": "relevant",
    "reason": "Der Lageberich nennt finanzielle Leistungsindikatoren (z.B. Eigenkapitalquote) und deren Berechnung. Die Pflicht ist immer anwendbar, da ein Lagebericht vorliegt."
  },
  "R19": {
    "label": "relevant",
    "reason": "Das Anlagevermögen ist in der Bilanz vorhanden (Buchwert > 0). Die Pflicht zur Darstellung des Anlagenspiegels ist daher anwendbar."
  },
  "R22": {
    "label": "unclear",
    "reason": "Die Pflicht ist bedingt: Sie greift nur, wenn Geschäftsführungs- oder Aufsichtsratsmitglieder vorhanden sind und die Schutzklausel nach § 286 Abs. 4 HGB nicht in Anspruch genommen wird. Im Jahresabschluss werden die Gesamtbezüge nicht angegeben, sodass nicht eindeutig feststellbar ist, ob die Schutzklausel angewandt wurde und die Pflicht damit entfällt."
  },
  "R23": {
    "label": "not_relevant",
    "reason": "Die Bilanz enthält keinen entgeltlich erworbenen Geschäfts- oder Firmenwert. Die Pflicht ist nur anwendbar, wenn ein solcher Posten in der Bilanz aktiviert ist."
  },
  "R24": {
    "label": "not_relevant",
    "reason": "Es sind keine latenten Steuern in der Bilanz bilanziert (im Anhang wird ausgeführt, dass keine latenten Steuern nach dem Mindeststeuergesetz berücksichtigt wurden). Die Pflicht ist nur anwendbar, wenn latente Steuern (aktiv oder passiv) vorhanden sind."
  }
}

{
  "R02": {
    "label": "relevant",
    "reason": "Prognosebericht vorhanden; der Prognosezeitraum wird im Lagebericht (2025, auch 2026) genannt, wenngleich nicht als explizit benannte Kenngröße. Die Pflicht ist aufgrund Vorliegens eines Prognoseberichts grundsätzlich anwendbar."
  },
  "R03": {
    "label": "relevant",
    "reason": "Prognosebericht vorhanden; wesentliche Annahmen werden genannt (wirtschaftliche Situation, Auftragseingang, prognostizierte Entwicklung der Bosch-Gruppe, Strukturkostenreduzierung, Beratervergütungen)."
  },
  "R04": {
    "label": "relevant",
    "reason": "Prognosebericht vorhanden; Prognosen zu den bedeutsamsten Leistungsindikatoren (Beratertage, Umsatz, Ergebnis) werden für 2025 dargestellt."
  },
  "R10": {
    "label": "relevant",
    "reason": "Risiko- und Chancenbericht ist Bestandteil des Lageberichts; Darstellung der Bedeutung der Risiken/Chancen ist anwendbar."
  },
  "R11": {
    "label": "relevant",
    "reason": "Risiko- und Chancenbericht vorhanden; eine zusammenfassende Gesamtaussage zur Risiko- und Chancenlage ist für dieses Unternehmen anwendbar."
  },
  "R12": {
    "label": "relevant",
    "reason": "Das Unternehmen nutzt Finanzinstrumente: Beteiligung am Cash-Pool der RB sowie erhebliche Forderungen/Verbindlichkeiten gegenüber verbundenen Unternehmen. Die Bedeutung für die Beurteilung der Lage (Liquiditätsversorgung) ist gegeben."
  },
  "R14": {
    "label": "relevant",
    "reason": "Lagebericht ist aufzustellen (mittelgroße Kapitalgesellschaft); Analyse der Ertragslage ist stets anwendbar."
  },
  "R15": {
    "label": "relevant",
    "reason": "Lagebericht ist aufzustellen; Analyse der Finanzlage ist stets anwendbar."
  },
  "R17": {
    "label": "relevant",
    "reason": "Lagebericht vorhanden; das Unternehmen verwendet bedeutsamste finanzielle Leistungsindikatoren (Beratertage, Umsatz, Ergebnis, Strukturkosten) zur internen Steuerung, die in die Analyse einzubeziehen sind."
  },
  "R19": {
    "label": "relevant",
    "reason": "Anlagevermögen in Bilanz vorhanden (388 TEUR > 0); ein Anlagenspiegel ist gem. § 284 Abs. 3 HGB erforderlich."
  },
  "R22": {
    "label": "relevant",
    "reason": "Geschäftsführer vorhanden (Baden, Hoffmann), sodass die Grundpflicht nach § 285 Nr. 9 lit. a HGB anwendbar ist. Die Schutzklausel des § 286 Abs. 4 HGB wird in Anspruch genommen – sie betrifft die tatsächliche Angabe, nicht die Anwendbarkeit der Pflicht selbst."
  },
  "R23": {
    "label": "not_relevant",
    "reason": "In der Bilanz ist kein entgeltlich erworbener Geschäfts- oder Firmenwert aktiviert; die immateriellen Vermögensgegenstände (CRM-Software) stellen keinen Firmenwert dar."
  },
  "R24": {
    "label": "not_relevant",
    "reason": "Es sind keine bilanzierten latenten Steuern (weder aktiv noch passiv) in der Bilanz oder im Anhang ausgewiesen; Bewertungsunterschiedsbetrag nach § 253 Abs. 6 HGB betrifft Pensionsrückstellungen, nicht latente Steuern."
  }
}

{
  "R02": {
    "label": "relevant",
    "reason": "Der Lagebericht enthält einen Prognosebericht (Abschnitt 4), sodass die Pflicht zur Angabe des Prognosezeitraums gilt. Im Text wird der Prognosezeitraum nicht explizit benannt (nur 'Geschäftsjahr 2025' und Teilbetrachtungen)."
  },
  "R03": {
    "label": "relevant",
    "reason": "Für den Prognosebericht besteht die Pflicht, wesentliche Annahmen darzustellen. Im Bericht werden nur grobe Trends (z. B. Wachstumsmarkt, Remote Work) genannt, aber keine quantifizierten Annahmen offengelegt."
  },
  "R04": {
    "label": "relevant",
    "reason": "Im Wirtschaftsbericht werden bedeutsamste finanzielle (z. B. Buchungserlöse, Umsatzerlöse) und nichtfinanzielle Leistungsindikatoren (z. B. Buchungen) verwendet, sodass Prognosen hierzu erforderlich wären."
  },
  "R10": {
    "label": "relevant",
    "reason": "Der Risiko- und Chancenbericht ist vorhanden, daher muss die Bedeutung der Risiken/Chancen dargestellt werden (z. B. durch Rangordnung). Im Bericht werden Risiken thematisch gruppiert, aber keine quantitative Einordnung vorgenommen."
  },
  "R11": {
    "label": "relevant",
    "reason": "Eine zusammenfassende Gesamtaussage zur Risiko- und Chancenlage ist Pflicht. Im Bericht wird lediglich festgestellt, dass keine bestandsgefährdenden Risiken vorliegen, aber keine explizite Gesamtbewertung der Chancenlage gegeben."
  },
  "R12": {
    "label": "relevant",
    "reason": "Die Gesellschaft verwendet Finanzinstrumente (z. B. Fremdwährungsrisiken, Call-/Put-Optionen, Derivate), was einen Finanzrisikobericht erfordert."
  },
  "R14": {
    "label": "relevant",
    "reason": "Eine Analyse der Ertragslage ist für den Lagebericht vorgeschrieben. Im Bericht wird die Ertragslage detailliert analysiert (Umsatzentwicklung, Aufwandsentwicklung, Ergebnisentwicklung)."
  },
  "R15": {
    "label": "relevant",
    "reason": "Eine Analyse der Finanzlage ist Pflicht. Im Bericht wird die Finanzlage (Kapitalstruktur, Investitionen, Liquidität) analysiert."
  },
  "R17": {
    "label": "relevant",
    "reason": "Die bedeutsamsten finanziellen Leistungsindikatoren (z. B. Buchungserlöse, Umsatzerlöse) werden im Wirtschaftsbericht verwendet und müssen in die Analyse einbezogen werden."
  },
  "R19": {
    "label": "relevant",
    "reason": "Das Anlagevermögen ist in der Bilanz vorhanden, sodass ein Anlagenspiegel gemäß § 284 Abs. 3 HGB erforderlich ist."
  },
  "R22": {
    "label": "relevant",
    "reason": "Die Gesellschaft hat eine Geschäftsführung (Organmitglieder), sodass die Angabe der Gesamtbezüge erforderlich ist, sofern nicht die Schutzklausel des § 286 Abs. 4 HGB greift."
  },
  "R23": {
    "label": "not_relevant",
    "reason": "In der Bilanz wird kein entgeltlich erworbener Geschäfts- oder Firmenwert ausgewiesen (nur selbst geschaffene und erworbene immaterielle Vermögensgegenstände)."
  },
  "R24": {
    "label": "relevant",
    "reason": "Latente Steuern werden im Anhang erläutert (aktive/passive latente Steuern), sodass die Grundlagen (Differenzen, Verlustvorträge, Steuersätze) darzulegen sind."
  }
}

